#include <string>
#include <algorithm>
#include <cmath>
using namespace std;

class Solution {
public:
    int minCost(string s, string t, int flip_cost, int swap_cost) {
        int c01 = 0, c10 = 0;
        for (int i = 0; i < (int)s.size(); i++) {
            if (s[i] == '0' && t[i] == '1') c01++;
            if (s[i] == '1' && t[i] == '0') c10++;
        }
        int pairs = min(c01, c10);
        int rem = abs(c01 - c10);
        return pairs * min(swap_cost, 2 * flip_cost) + rem * flip_cost;
    }
};

class Solution {
    public int minCost(String s, String t, int flipCost, int swapCost) {
        int c01 = 0, c10 = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '0' && t.charAt(i) == '1') c01++;
            if (s.charAt(i) == '1' && t.charAt(i) == '0') c10++;
        }
        int pairs = Math.min(c01, c10);
        int rem = Math.abs(c01 - c10);
        return pairs * Math.min(swapCost, 2 * flipCost) + rem * flipCost;
    }
}

